use super::*;
use crate::stages::post::{Output, tone_map};
use crate::test_support::{half, hdr_texture, read};

// Expected bytes were generated by compiling the pinned AMD header's
// original filter functions, not by evaluating the WGSL port. See the
// reproducible generator and provenance beside these fixtures.
#[test]
fn coloured_edges_match_the_independent_amd_header_oracle() {
    let Some((device, queue)) = crate::test_support::device() else {
        return;
    };
    let inputs = Inputs::new(&device);
    let mut fsr = Fsr1::new(&device, &inputs);
    let linear: Vec<_> = (0..3)
        .flat_map(|y| {
            (0..4).map(move |x| {
                let r = ((x + 2 * y) % 4 + 1) as f32 / 4.;
                let g = ((3 * x + y) % 4 + 1) as f32 / 4.;
                let b = ((x + y) % 3 + 1) as f32 / 4.;
                [r * r, g * g, b * b, 1.]
            })
        })
        .collect();
    let source = hdr_texture(&device, &queue, [4, 3], &linear);
    let bloom = target(&device, "unused bloom", [1, 1], HDR);
    let mut encoder = device.create_command_encoder(&Default::default());
    let easu = fsr.encode(
        &device,
        &mut encoder,
        &inputs,
        &source,
        &bloom,
        [7, 5],
        None,
    );
    let output = target(&device, "oracle output", [7, 5], HDR);
    let mut mapper = tone_map::ToneMap::new(&device, &inputs, Output::texture(HDR), [7, 5]);
    mapper.resample(
        &device,
        &mut encoder,
        &inputs,
        easu,
        &bloom,
        true,
        tone_map::Reconstruction::Rcas,
        &output,
        None,
    );
    queue.submit([encoder.finish()]);
    let actual = [
        read(&device, &queue, easu.texture(), 8),
        read(&device, &queue, mapper.tone_mapped().texture(), 8),
    ];
    let expected = include_bytes!("../../../../tests/fixtures/fsr1/amd-reference.rgb32");
    for (pass, image) in actual.iter().enumerate() {
        let mut reference_error = 0f32;
        for (pixel, texel) in image.chunks_exact(8).enumerate() {
            assert_eq!(half(&texel[6..]), 1.);
            for channel in 0..3 {
                let offset = (pass * 35 * 3 + pixel * 3 + channel) * 4;
                let reference =
                    f32::from_le_bytes(expected[offset..offset + 4].try_into().unwrap());
                let value = half(&texel[channel * 2..]);
                assert!(value.is_finite());
                reference_error = reference_error.max((value - reference).abs());
                // Half intermediate/output roundoff plus f32 CPU/GPU
                // operation order, under three half-float steps near 1.
                assert!(
                    (value - reference).abs() < 0.003,
                    "pass {pass}, pixel {pixel}, channel {channel}: {value} vs AMD {reference}"
                );
            }
        }
        eprintln!("FSR1 oracle pass {pass}: max error from original SDK {reference_error}");
    }
}

// Direct kernel inputs, without tone mapping lowering white before RCAS.
// A flat white has zero sharpening lobe; AMD's original medium reciprocal
// of 1 is 0.9968469, whose gamma-2 decode is 0.9937038. Keep that bounded
// upstream behaviour, while defining its singular 0/0 limiters explicitly.
#[test]
fn direct_black_and_white_are_finite_and_keep_the_sdk_flat_response() {
    let Some((device, queue)) = crate::test_support::device() else {
        return;
    };
    let inputs = Inputs::new(&device);
    let mut fsr = Fsr1::new(&device, &inputs);
    let bloom = target(&device, "unused flat bloom", [1, 1], HDR);
    let output = target(&device, "flat kernel result", [7, 5], HDR);
    let mut mapper = tone_map::ToneMap::new(&device, &inputs, Output::texture(HDR), [7, 5]);
    for (input, expected) in [(0., 0.), (1., 0.9937038)] {
        let source = hdr_texture(&device, &queue, [4, 3], &[[input, input, input, 1.]; 12]);
        let mut encoder = device.create_command_encoder(&Default::default());
        let easu = fsr.encode(
            &device,
            &mut encoder,
            &inputs,
            &source,
            &bloom,
            [7, 5],
            None,
        );
        mapper.resample(
            &device,
            &mut encoder,
            &inputs,
            easu,
            &bloom,
            true,
            tone_map::Reconstruction::Rcas,
            &output,
            None,
        );
        queue.submit([encoder.finish()]);
        for pixel in read(&device, &queue, mapper.tone_mapped().texture(), 8).chunks_exact(8) {
            for channel in 0..3 {
                let value = half(&pixel[channel * 2..]);
                assert!(value.is_finite());
                assert!(
                    (value - expected).abs() < 0.001,
                    "flat {input}: {value} vs upstream {expected}"
                );
            }
            assert_eq!(half(&pixel[6..]), 1.);
        }
    }
}
